INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('1dfb964f-773f-573c-9e7a-a90eb7a9a001', 'a556b622-21d0-5007-9060-fa7e526ad4ac', 1, 'Convocatoria · CFE-0900-CASAT-0025-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD</p>
<p>CONVOCATORIA</p>
<p>Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, 80 y 82 de la Ley de la Comisión Federal de Electricidad, en las disposiciones 2, fracción II, 30 fracción I, inciso b), 31, 37 fracción I de las Disposiciones Generales en Materia de adquisiciones, arrendamientos, contratación de servicios y ejecución de obras de la CFE, se hace saber a los interesados la publicación de la Concurso Abierto Internacional Bajo la Cobertura de los Tratados, de conformidad con lo siguiente:</p>
<table><tbody><tr><th scope="row">Número del Concurso:</th><td>CFE-0900-CASAT-0025-2026</td></tr><tr><th scope="row">Descripción de Concurso:</th><td>Mantenimiento al generador Eléctrico U5 de la Central Ciclo Combinado Felipe Carrillo Puerto</td></tr><tr><th scope="row">Publicación en Micrositio CFE:</th><td>10/11/2026</td></tr><tr><th scope="row">Sesión de Aclaraciones:</th><td>13/11/2026, 10:00 hrs</td></tr><tr><th scope="row">Límite para presentación de ofertas:</th><td>20/11/2026, 08:00 hrs</td></tr><tr><th scope="row">Apertura Técnica:</th><td>20/11/2026, 08:00 hrs</td></tr><tr><th scope="row">Apertura Económica:</th><td>27/11/2026, 09:00 hrs</td></tr><tr><th scope="row">Fallo</th><td>04/12/2026, 10:00 hrs</td></tr></tbody></table>
<p>El Area Contratante que publica la presente convocatoria es la Coordinación Regional de Producción Sureste, con clave 0900, a través del Departamento Regional de Abastecimientos, cuyo contacto es la LMNI. Issis América Espino Ramírez, Jefa Departamento Regional de Abastecimientos E.F. de la Sede de la Coordinación Regional de Producción Sureste con Clave de Agente Contratante A190001, con domicilio en el Km. 7.5 Carretera Veracruz-Medellín, Dos Bocas, Veracruz, C.P. 94271, teléfono 2299898595, extensión: 77380, correo electrónico: issis.espino@cfe.mx.</p>
<p>CIUDAD DE VERACRUZ, VER., A 10 DE NOVIEMBRE DE 2026. JEFA DEL DEPARTAMENTO REGIONAL DE ABASTECIMIENTOS E.F.</p>
<p>LMNI. ISSIS AMERICA ESPINO RAMIREZ</p>
<p>FIRMA ELECTRONICA.</p>
<p>(R.- 582157)</p>', 'convocatoria', 'CFE-0900-CASAT-0025-2026', 'Mantenimiento del generador de la unidad 5 de Felipe Carrillo Puerto', NULL);
